import requests
from PIL import Image
from io import BytesIO

def check_image_for_unsafe_content(image_url):
    subscription_key = "your_subscription_key"
    endpoint = "https://westcentralus.api.cognitive.microsoft.com/"
    content_mode = 'Raw'
    visual_features = 'Adult'

    headers = {
        'Content-Type': 'application/octet-stream',
        'Ocp-Apim-Subscription-Key': subscription_key
    }

    params = {
        'visualFeatures': visual_features,
        'language': 'en',
    }

    image_data = requests.get(image_url).content
    response = requests.post(endpoint + "vision/v3.2/analyze", headers=headers, params=params, data=image_data)
    response.raise_for_status()
    analysis = response.json()

    if 'adult' in analysis:
        is_adult_content = analysis['adult']['isAdultContent']
        is_racy_content = analysis['adult']['isRacyContent']
        return {
            'is_adult_content': is_adult_content,
            'is_racy_content': is_racy_content
        }
    else:
        return {
            'is_adult_content': None,
            'is_racy_content': None
        }
